        // reshaping 01 ranges
        // Based on: http://sol.gfxile.net/interpolation/index.html
        public static float SmoothStep(float val) => val * val * (3 - 2 * val);

        public static float SmootherStep(float val) => val * val * val * (val * (val * 6 - 15) + 10);

        public static float SinShape(float val) => Sin(Clamp01(val) * HALF_PI);
        public static float CosShape(float val) => 1 - Cos(Clamp01(val) * HALF_PI);

        public static float SymmetricSinShape(float val) => Sin(Clamp01(val) * PI);

        // Symmetric pow shape
        public static float SymmetricPowShape(float val, float pow)
        {
            if (val < 0.5f)
                return (1f - MathX.Pow(1f - (val * 2), pow)) * 0.5f;
            else
                return 0.5f + (MathX.Pow((val - 0.5f) * 2, pow)) * 0.5f;
        }

        public static float Sigmoid(float x, float e = E) => 1 / (1 + Pow(e, -x));
        public static float SigmoidInv(float x, float e = E) => Log(x / (1 - x), e);

        public static float SquareCentered01(float x)
        {
            x -= 0.5f;
            x *= x * MathX.Sign(x);

            return x * 2 + 0.5f;
        }

        public static float InvSquareCentered01(float x)
        {
            x -= 0.5f;
            x *= 0.5f;
            x = MathX.Sqrt(MathX.Abs(x)) * MathX.Sign(x);
            return x + 0.5f;
        }

		public static uint4 QuantizeQuaternion(in floatQ value, int bits)
        {
            // find the largest component
            var max = float.MinValue;
            int maxIndex = -1;
            for (int i = 0; i < 4; i++)
            {
                var val = Abs(value[i]);
                if(val > max)
                {
                    max = val;
                    maxIndex = i;
                }
            }

            float3 abc;
            bool sign;

            switch(maxIndex)
            {
                case 0:
					abc = value.yzw;
                    sign = value.x < 0;
                    break;

                case 1:
					abc = value.xzw;
                    sign = value.y < 0;
                    break;

                case 2:
					abc = value.xyw;
                    sign = value.z < 0;
                    break;

                case 3:
					abc = value.xyz;
                    sign = value.w < 0;
                    break;

                default:
                    // shouldn't ever happen
					#if DEBUG
                    throw new Exception("Invalid max index");
					#else
					abc = default;
					sign = default;
					break;
					#endif
            }

			var q = Quantize(Asin(abc), -HALF_PI, HALF_PI, bits);

			// encode the sign and largest element in the fourth value, using three bits
            return new uint4(q, ((sign ? 1U : 0U) << 2) | (uint)maxIndex );
        }

		public static floatQ DequantizeQuaternion(in uint4 value, int bits)
        {
			var abc = Dequantize(value.xyz, -HALF_PI, HALF_PI, bits);
			abc = Sin(abc);

            var d = Sqrt(Max(0, 1 - abc.SqrMagnitude)) * (((value.w & (1<<2)) == 0) ? 1 : -1);

            uint maxIndex = value.w & 0x03U; // get which one of the components was larger

            switch(maxIndex)
            {
                case 0:
                    return new floatQ(d, abc.x, abc.y, abc.z);

                case 1:
                    return new floatQ(abc.x, d, abc.y, abc.z);

                case 2:
                    return new floatQ(abc.x, abc.y, d, abc.z);

                case 3:
                    return new floatQ(abc.x, abc.y, abc.z, d);

                default:
                    // shouldn't be possible to happen, but needs to satisfy the compiler
					#if DEBUG
                    throw new Exception("Invalid MaxIndex");
					#else
					return default;
					#endif
            }
        }

        public static floatQ PackSmallest3(floatQ q)
        {
            // Find the biggest component
            var abs = MathX.Abs((float4)q);
            var index = MathX.MaxComponentIndex(abs);
            var maxV = abs[index];

            if (index == 0) q = (floatQ)q.yzwx;
            if (index == 1) q = (floatQ)q.xzwy;
            if (index == 2) q = (floatQ)q.xywz;

            var three = q.xyz * (q.w >= 0 ? 1 : -1); // -1/sqrt2..+1/sqrt2 range
            three = (three * MathX.SQRT2) * 0.5f + 0.5f; // 0..1 range
             
            return new floatQ(three.x, three.y, three.z, index / 3.0f);
        }

        // 32 bits: 10.10.10.2
        public static uint EncodePackedQuaternionToNorm10(in floatQ v)
        {
            return (uint) (v.x * 1023.5f)
                | ((uint) (v.y * 1023.5f) << 10)
                | ((uint) (v.z * 1023.5f) << 20)
                | ((uint) (v.w * 3.5f) << 30);
        }

		
