        public static double3 BezierCurve(double3 from, double3 to, double3 fromTangent, double3 toTangent, float t)
        {
            var u = 1f - t;
            var tt = t * t;
            var uu = u * u;
            var ttt = tt * t;
            var uuu = uu * u;

            return uuu * from +
                (3 * uu * t * fromTangent) +
                (3 * u * tt * toTangent) +
                ttt * to;
        }

        public static double3 BezierTangent(double3 from, double3 to, double3 fromTangent, double3 toTangent, float t)
        {
            return -3f * MathX.Pow(1f - t, 2f) * from +
                3f * MathX.Pow(1f - t, 2f) * fromTangent -
                6f * t * (1f - t) * fromTangent -
                3f * MathX.Pow(t, 2f) * toTangent +
                6f * t * (1f - t) * toTangent +
                3f * MathX.Pow(t, 2f) * to;
        }

		public static void OffsetRangeToZero(in double3 min, in double3 max, int bits, out double3 newMin, out double3 newMax)
        {
            if((min < 0).Any() && (max > 0).Any())
            {
                var range = max - min;

                var steps = MaxValueForBits(bits);

                // what percent of the range is the zero in?
                var zeroPercentage = -min / range;

                var zeroValue = (ulong3)MathX.Round(zeroPercentage * steps);
                var rightSteps = steps - zeroValue;
                var leftSteps = steps - rightSteps;
                var leftRange = -min;
                var rightRange = max;

                var leftStepSize = leftRange / leftSteps;
                var rightStepSize = rightRange / rightSteps;

                var newStepSize = MathX.Max(leftStepSize, rightStepSize);

                newMin = -(leftSteps * newStepSize);
                newMax = rightSteps * newStepSize;
            }
            else
            {
                newMin = min;
                newMax = max;
            }
        }

