                public static ulong EncodeFloat3ToNorm16(in double3 v) // 48 bits: 16.16.16
                {
                    return (ulong) (v.x * 65535.5) | ((ulong) (v.y * 65535.5) << 16) | ((ulong) (v.z * 65535.5) << 32);
                }
                public static uint EncodeFloat3ToNorm11(in double3 v) // 32 bits: 11.10.11
                {
                    return (uint) (v.x * 2047.5) | ((uint) (v.y * 1023.5) << 11) | ((uint) (v.z * 2047.5) << 21);
                }
                public static ushort EncodeFloat3ToNorm655(in double3 v) // 16 bits: 6.5.5
                {
                    return (ushort) ((uint) (v.x * 63.5) | ((uint) (v.y * 31.5) << 6) | ((uint) (v.z * 31.5) << 11));
                }
                public static ushort EncodeFloat3ToNorm565(in double3 v) // 16 bits: 5.6.5
                {
                    return (ushort) ((uint) (v.x * 31.5) | ((uint) (v.y * 63.5) << 5) | ((uint) (v.z * 31.5) << 11));
                }

                
